const TIMEOUT_MS = 500;

export async function renderWidgets(queue, draw) {
  const started = Date.now();
  for (const widget of queue) {
    if (Date.now() - started > TIMEOUT_MS) throw new Error('render aborted');
    await draw(widget);
  }
}

